#define SCRNSVR 1
precision highp float;

#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;
uniform float speed;
uniform float waves;
uniform float spread;
uniform float brightness;
uniform vec3 color1;
uniform vec3 color2;
uniform float saturation;
uniform int curtains;
uniform float verticalPosition;
uniform float amplitude;
uniform float foldDetail;
uniform vec3 background;
uniform vec3 backgroundTop;
#else
#define uTime iTime
#define uResolution iResolution.xy
const float speed = 0.3;
const float waves = 1.5;
const float spread = 0.45;
const float brightness = 1.0;
const vec3 color1 = vec3(0.219608, 0.909804, 0.729412);
const vec3 color2 = vec3(0.572549, 0.439216, 1.000000);
const float saturation = 1.0;
const int curtains = 3;
const float verticalPosition = 0.0;
const float amplitude = 1.0;
const float foldDetail = 1.0;
const vec3 background = vec3(0.007843, 0.015686, 0.050980);
const vec3 backgroundTop = vec3(0.035294, 0.054902, 0.129412);
#endif

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = (fragCoord / uResolution);
  float t = uTime * speed;
  vec3 color = mix(background, backgroundTop, p.y);
  for (int i = 0; i < 5; i++) {
    if (i >= curtains) continue;
    float layer = float(i);
    float phase = p.x * waves * 3.0 + layer * 1.8;
    float center = 0.3 + verticalPosition + layer * 0.17
      + amplitude * 0.12 * sin(phase + t * 0.35)
      + amplitude * 0.05 * sin(phase * 2.3 - t * 0.27);
    float distance = p.y - center;
    // A narrow lower edge opens into a broad translucent curtain above it.
    float width = mix(0.025, 0.12, spread) * (1.0 + 2.5 * smoothstep(-0.02, 0.2, distance));
    float curtain = exp(-distance * distance / (width * width));
    float folds = 0.72 + 0.28 * sin(phase * 5.0 * foldDetail + sin(phase * 1.7 + t * 0.2) - t * 0.4);
    vec3 tint = mix(color1, color2, 0.5 + 0.5 * sin(p.x * 2.5 + layer * 1.6 + t * 0.15));
    color += tint * curtain * folds * 0.5 * brightness;
  }
  float dither = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
  fragColor = vec4(clamp(color + (dither - 0.5) / 255.0, 0.0, 1.0), 1.0);
  float luminance = dot(fragColor.rgb, vec3(0.2126, 0.7152, 0.0722));
  fragColor.rgb = mix(vec3(luminance), fragColor.rgb, saturation);
}
void main() {
  vec4 color = vec4(0.0);
  mainImage(color, gl_FragCoord.xy);
  gl_FragColor = vec4(color.rgb, 1.0);
}

#define SCRNSVR 1
precision highp float;

#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;
uniform float speed;
uniform float size;
uniform float softness;
uniform float travel;
uniform float opacity;
uniform vec3 color1;
uniform vec3 color2;
uniform vec3 color3;
uniform vec3 background;
uniform float brightness;
uniform float saturation;
#else
#define uTime iTime
#define uResolution iResolution.xy
const float speed = 0.3;
const float size = 1.0;
const float softness = 0.012;
const float travel = 1.0;
const float opacity = 0.8;
const vec3 color1 = vec3(0.937255, 0.694118, 0.549020);
const vec3 color2 = vec3(0.709804, 0.639216, 0.862745);
const vec3 color3 = vec3(0.454902, 0.741176, 0.709804);
const vec3 background = vec3(0.941176, 0.909804, 0.858824);
const float brightness = 1.0;
const float saturation = 1.0;
#endif

// Static sub-byte dithering preserves broad gradients without temporal grain.
vec4 finish(vec3 color) {
  color = clamp(color * brightness, 0.0, 1.0);
  float dither = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
  color = clamp(color + (dither - 0.5) / 255.0 * min(brightness, 1.0), 0.0, 1.0);
  float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
  return vec4(clamp(mix(vec3(luminance), color, saturation), 0.0, 1.0), 1.0);
}

vec3 palette(float phase) {
  return mix(mix(color1, color2, smoothstep(0.0, 0.5, phase)), color3, smoothstep(0.5, 1.0, phase));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 aspect = uResolution / min(uResolution.x, uResolution.y);
  vec2 p = (fragCoord / uResolution - 0.5) * aspect;
  float t = uTime * speed;
  float aa = max(softness, 1.5 / min(uResolution.x, uResolution.y));
  vec3 color = background;
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float phase = fi * 2.094395;
    vec2 center = travel * vec2(0.22 * min(aspect.x, 1.8) * cos(t * (0.18 + fi * 0.021) + phase),
      0.20 * sin(t * (0.21 - fi * 0.017) + phase));
    vec2 q = p - center;
    float a = 0.35 * sin(t * 0.13 + phase) + phase;
    q = mat2(cos(a), -sin(a), sin(a), cos(a)) * q;
    // The middle shape is a capsule; the others remain circular.
    q.x -= clamp(q.x, -0.12 * size * float(i == 1), 0.12 * size * float(i == 1));
    float radius = size * (i == 1 ? 0.23 : 0.30);
    float mask = 1.0 - smoothstep(radius - aa, radius + aa, length(q));
    vec3 tint = i == 0 ? color1 : (i == 1 ? color2 : color3);
    tint = mix(tint, vec3(1.0), 0.13 * clamp(0.5 + q.y / (2.0 * radius), 0.0, 1.0));
    // Multiplicative pigment keeps intersections visible without a lighting model.
    color *= mix(vec3(1.0), tint, mask * opacity);
  }
  fragColor = finish(color);
}
void main() {
  vec4 color = vec4(0.0);
  mainImage(color, gl_FragCoord.xy);
  gl_FragColor = vec4(color.rgb, 1.0);
}

#define SCRNSVR 1
precision highp float;

#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;
uniform float speed;
uniform float channelWidth;
uniform float curvature;
uniform float angle;
uniform float drift;
uniform vec3 color1;
uniform vec3 color2;
uniform vec3 color3;
uniform vec3 background;
uniform float brightness;
uniform float saturation;
#else
#define uTime iTime
#define uResolution iResolution.xy
const float speed = 0.3;
const float channelWidth = 0.12;
const float curvature = 0.65;
const float angle = 20.0;
const float drift = 0.75;
const vec3 color1 = vec3(0.686275, 0.780392, 0.721569);
const vec3 color2 = vec3(0.874510, 0.803922, 0.666667);
const vec3 color3 = vec3(0.549020, 0.670588, 0.709804);
const vec3 background = vec3(0.207843, 0.396078, 0.458824);
const float brightness = 1.0;
const float saturation = 1.0;
#endif

// Static sub-byte dithering preserves broad gradients without temporal grain.
vec4 finish(vec3 color) {
  color = clamp(color * brightness, 0.0, 1.0);
  float dither = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
  color = clamp(color + (dither - 0.5) / 255.0 * min(brightness, 1.0), 0.0, 1.0);
  float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
  return vec4(clamp(mix(vec3(luminance), color, saturation), 0.0, 1.0), 1.0);
}

vec3 palette(float phase) {
  return mix(mix(color1, color2, smoothstep(0.0, 0.5, phase)), color3, smoothstep(0.5, 1.0, phase));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = (fragCoord / uResolution - 0.5) * uResolution / min(uResolution.x, uResolution.y);
  float t = uTime * speed;
  float a = radians(angle);
  p = mat2(cos(a), -sin(a), sin(a), cos(a)) * p;
  p -= drift * 0.10 * vec2(sin(t * 0.19), cos(t * 0.16));
  vec2 q = p + curvature * 0.16 * vec2(sin(p.y * 3.4 + t * 0.17), sin(p.x * 3.0 - t * 0.13));
  float nearest = 100.0;
  float nextNearest = 100.0;
  vec3 tint = color1;
  // Three moving regions meet at one junction; their distance differences form the channels.
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float phase = fi * 2.094395;
    vec2 site = 0.75 * vec2(cos(phase), sin(phase));
    float distance = length(q - site);
    if (distance < nearest) {
      nextNearest = nearest;
      nearest = distance;
      tint = i == 0 ? color1 : (i == 1 ? color2 : color3);
    } else nextNearest = min(nextNearest, distance);
  }
  float width = channelWidth * (1.0 + drift * 0.12 * sin(t * 0.22 + p.y * 2.0));
  float aa = 2.5 / min(uResolution.x, uResolution.y);
  float land = smoothstep(width - aa, width + aa, nextNearest - nearest);
  tint *= 0.92 + 0.08 * smoothstep(-0.6, 0.6, p.y);
  fragColor = finish(mix(background, tint, land));
}
void main() {
  vec4 color = vec4(0.0);
  mainImage(color, gl_FragCoord.xy);
  gl_FragColor = vec4(color.rgb, 1.0);
}

#define SCRNSVR 1
precision highp float;

#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;
uniform float speed;
uniform int shapeCount;
uniform float size;
uniform float sway;
uniform float travel;
uniform vec3 color1;
uniform vec3 color2;
uniform vec3 color3;
uniform vec3 background;
uniform float brightness;
uniform float saturation;
#else
#define uTime iTime
#define uResolution iResolution.xy
const float speed = 0.3;
const int shapeCount = 6;
const float size = 1.0;
const float sway = 0.8;
const float travel = 0.6;
const vec3 color1 = vec3(0.894118, 0.792157, 0.517647);
const vec3 color2 = vec3(0.800000, 0.549020, 0.509804);
const vec3 color3 = vec3(0.470588, 0.584314, 0.596078);
const vec3 background = vec3(0.145098, 0.176471, 0.231373);
const float brightness = 1.0;
const float saturation = 1.0;
#endif

// Static sub-byte dithering preserves broad gradients without temporal grain.
vec4 finish(vec3 color) {
  color = clamp(color * brightness, 0.0, 1.0);
  float dither = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
  color = clamp(color + (dither - 0.5) / 255.0 * min(brightness, 1.0), 0.0, 1.0);
  float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
  return vec4(clamp(mix(vec3(luminance), color, saturation), 0.0, 1.0), 1.0);
}

vec3 palette(float phase) {
  return mix(mix(color1, color2, smoothstep(0.0, 0.5, phase)), color3, smoothstep(0.5, 1.0, phase));
}

float roundedBox(vec2 p, vec2 halfSize, float radius) {
  vec2 q = abs(p) - halfSize + radius;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - radius;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 aspect = uResolution / min(uResolution.x, uResolution.y);
  vec2 p = (fragCoord / uResolution - 0.5) * aspect;
  float t = uTime * speed;
  float aa = 1.5 / min(uResolution.x, uResolution.y);
  vec3 color = background;
  for (int i = 0; i < 8; i++) {
    if (i >= shapeCount) continue;
    float fi = float(i);
    float phase = fi * 2.399963;
    // Staggered rows give the pieces room to rock without crowding their neighbors.
    float rows = ceil(float(shapeCount) / 3.0);
    vec2 center = aspect * vec2((mod(fi, 3.0) - 1.0) * 0.30,
      (floor(fi / 3.0) - (rows - 1.0) * 0.5) * 0.62 / rows);
    center += 0.035 * vec2(sin(phase), cos(phase));
    center += travel * 0.045 * vec2(sin(t * 0.19 + phase), cos(t * 0.23 + phase));
    vec2 q = p - center;
    float a = phase * 0.5 + sway * 0.25 * sin(t * 0.2 + phase);
    q = mat2(cos(a), -sin(a), sin(a), cos(a)) * q;
    float radius = size * (0.095 + 0.025 * sin(phase + 0.8));
    float kind = mod(fi + floor(fi / 3.0), 3.0);
    float distance = length(q) - radius;
    if (kind < 0.5) distance = max(length(q) - radius * 1.3, -q.y);
    else if (kind < 1.5) distance = roundedBox(q, vec2(radius * 1.35, radius * 0.48), radius * 0.3);
    float mask = 1.0 - smoothstep(-aa, aa, distance);
    vec3 tint = kind < 0.5 ? color1 : (kind < 1.5 ? color2 : color3);
    tint *= 0.85 + 0.15 * smoothstep(-radius, radius, q.y);
    color = mix(color, tint, mask);
  }
  fragColor = finish(color);
}
void main() {
  vec4 color = vec4(0.0);
  mainImage(color, gl_FragCoord.xy);
  gl_FragColor = vec4(color.rgb, 1.0);
}

#define SCRNSVR 1
precision highp float;

#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;
uniform float speed;
uniform float scale;
uniform float lines;
uniform float brightness;
uniform vec3 color1;
uniform vec3 color2;
uniform float saturation;
uniform float lineThickness;
uniform float edgeSoftness;
uniform float distortion;
uniform float fineDetail;
uniform float angle;
uniform float contourIntensity;
#else
#define uTime iTime
#define uResolution iResolution.xy
const float speed = 0.2;
const float scale = 1.0;
const float lines = 10.0;
const float brightness = 1.0;
const vec3 color1 = vec3(0.098039, 0.152941, 0.266667);
const vec3 color2 = vec3(0.839216, 0.627451, 0.419608);
const float saturation = 1.0;
const float lineThickness = 0.025;
const float edgeSoftness = 0.025;
const float distortion = 0.55;
const float fineDetail = 0.08;
const float angle = 0.0;
const float contourIntensity = 1.0;
#endif

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = ((fragCoord / uResolution) - 0.5) * vec2(uResolution.x / uResolution.y, 1.0) * scale * 3.0;
  float rotation = radians(angle);
  p = mat2(cos(rotation), sin(rotation), -sin(rotation), cos(rotation)) * p;
  float t = uTime * speed;
  vec2 q = p + distortion * vec2(sin(p.y * 1.2 + t * 0.24), cos(p.x * 0.9 - t * 0.18));
  float height = 0.5 + 0.23 * sin(q.x * 1.3 + q.y * 0.7 + t * 0.12)
    + 0.16 * cos(q.y * 1.8 - q.x * 0.4 - t * 0.17)
    + fineDetail * sin(q.x * 2.1 - q.y * 1.5);
  float band = abs(fract(height * lines) - 0.5);
  // Resolution-aware soft edges prevent fine contours from shimmering in previews.
  float softness = max(edgeSoftness, lines * scale * 3.0 / uResolution.y);
  float contour = 1.0 - smoothstep(lineThickness, lineThickness + softness, band);
  float ridge = 0.5 + 0.5 * sin(height * 6.283185);
  vec3 color = mix(color1 * 0.6, color1 + color2 * 0.16, height)
    + color2 * contourIntensity * contour * (0.25 + 0.25 * ridge);
  float dither = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
  fragColor = vec4(clamp((1.0 - exp(-color * brightness)) + (dither - 0.5) / 255.0 * min(brightness, 1.0), 0.0, 1.0), 1.0);
  float luminance = dot(fragColor.rgb, vec3(0.2126, 0.7152, 0.0722));
  fragColor.rgb = mix(vec3(luminance), fragColor.rgb, saturation);
}
void main() {
  vec4 color = vec4(0.0);
  mainImage(color, gl_FragCoord.xy);
  gl_FragColor = vec4(color.rgb, 1.0);
}

#define SCRNSVR 1
precision highp float;

#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;

uniform float speed;
uniform float scale;
uniform float distortion;
uniform float softness;
uniform float glow;
uniform float brightness;
uniform vec3 color1; // deep shadow
uniform vec3 color2; // midtone
uniform vec3 color3; // highlight
uniform float saturation;

#else
#define uTime iTime
#define uResolution iResolution.xy

const float speed      = 0.1;
const float scale      = 1.0;
const float distortion = 0.65;
const float softness   = 0.55;
const float glow       = 0.8;
const float brightness = 1.15;
const vec3 color1 = vec3(0.023529, 0.070588, 0.109804);
const vec3 color2 = vec3(0.101961, 0.329412, 0.368627);
const vec3 color3 = vec3(1.000000, 0.690196, 0.388235);
const float saturation = 0.9;
#endif


mat2 rotate2D(float a) {
    float c = cos(a);
    float s = sin(a);

    return mat2(
         c, -s,
         s,  c
    );
}


float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);

    return fract(p.x * p.y);
}


/*
    Smooth pseudo-noise without texture sampling.
*/
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    f = f * f * (3.0 - 2.0 * f);

    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));

    return mix(
        mix(a, b, f.x),
        mix(c, d, f.x),
        f.y
    );
}


float fbm(vec2 p) {
    float value = 0.0;
    float amplitude = 0.5;

    for (int i = 0; i < 4; i++) {
        value += noise(p) * amplitude;

        p = rotate2D(0.47) * p * 2.02;
        amplitude *= 0.5;
    }

    return value;
}


/*
    Distance from a slowly undulating ribbon.
*/
float ribbon(
    vec2 p,
    float offset,
    float frequency,
    float phase,
    float t
) {
    float wave =
          0.32 * sin(p.x * frequency + phase + t * 0.18)
        + 0.12 * sin(p.x * frequency * 0.47 - phase + t * 0.11)
        + 0.05 * sin(p.x * 2.4 - t * 0.08);

    return abs(p.y - wave - offset);
}


void mainImage(
    out vec4 fragColor,
    in vec2 fragCoord
) {
    vec2 uv = fragCoord / uResolution;

    vec2 p = uv - 0.5;
    p.x *= uResolution.x / uResolution.y;

    p *= scale * 2.35;

    float t = uTime * speed;


    // --------------------------------------------
    // Large-scale organic coordinate deformation
    // --------------------------------------------

    vec2 warp;

    warp.x = fbm(
        p * 0.48 +
        vec2(t * 0.035, -t * 0.018)
    );

    warp.y = fbm(
        p * 0.43 +
        vec2(4.7, 2.1) +
        vec2(-t * 0.021, t * 0.025)
    );

    warp = warp * 2.0 - 1.0;

    vec2 q = p + warp * distortion * 0.42;


    // --------------------------------------------
    // Main flowing surfaces
    // --------------------------------------------

    float d1 = ribbon(
        q,
        -0.28,
        1.05,
        0.0,
        t
    );

    float d2 = ribbon(
        q,
        0.08,
        0.82,
        1.8,
        t * 0.83
    );

    float d3 = ribbon(
        q,
        0.47,
        0.67,
        3.6,
        t * 0.68
    );


    float width1 = mix(0.08, 0.34, softness);
    float width2 = mix(0.10, 0.42, softness);
    float width3 = mix(0.14, 0.52, softness);


    float band1 =
        exp(-d1 * d1 / max(0.001, width1 * width1));

    float band2 =
        exp(-d2 * d2 / max(0.001, width2 * width2));

    float band3 =
        exp(-d3 * d3 / max(0.001, width3 * width3));


    // --------------------------------------------
    // Broad atmospheric gradient
    // --------------------------------------------

    float atmosphere =
        0.5 +
        0.5 * sin(
            q.x * 0.52 -
            q.y * 0.75 +
            t * 0.07
        );

    atmosphere = smoothstep(
        0.05,
        0.95,
        atmosphere
    );


    float field =
          band1 * 0.68
        + band2 * 0.44
        + band3 * 0.22;

    field += atmosphere * 0.20;

    field = clamp(field, 0.0, 1.0);


    // --------------------------------------------
    // Palette
    // --------------------------------------------

    vec3 col = mix(
        color1,
        color2,
        smoothstep(0.0, 0.72, field)
    );

    float highlight =
        pow(max(band1, band2 * 0.85), 2.2);

    col = mix(
        col,
        color3,
        highlight * 0.68
    );


    // --------------------------------------------
    // Soft luminous edge
    // --------------------------------------------

    float edgeDistance =
        min(d1, min(d2, d3));

    float halo =
        exp(
            -edgeDistance * edgeDistance /
            max(0.001, 0.16 + softness * 0.32)
        );

    col += color3 *
           halo *
           glow *
           0.18;


    // --------------------------------------------
    // Subtle depth / vignette
    // --------------------------------------------

    float radial =
        length(
            (uv - 0.5) *
            vec2(
                uResolution.x / uResolution.y,
                1.0
            )
        );

    col *= 1.0 - radial * 0.16;


    // --------------------------------------------
    // Film-like micro grain to reduce banding
    // --------------------------------------------

    float grain =
        hash21(
            fragCoord +
            fract(t) * 137.0
        ) - 0.5;

    col += grain / 255.0 * 1.4;


    // --------------------------------------------
    // Exposure
    // --------------------------------------------

    col =
        1.0 -
        exp(
            -max(col, 0.0) *
            brightness
        );


    // --------------------------------------------
    // Saturation
    // --------------------------------------------

    float luminance =
        dot(
            col,
            vec3(0.2126, 0.7152, 0.0722)
        );

    col = mix(
        vec3(luminance),
        col,
        saturation
    );


    fragColor = vec4(
        clamp(col, 0.0, 1.0),
        1.0
    );
}
void main() {
  vec4 color = vec4(0.0);
  mainImage(color, gl_FragCoord.xy);
  gl_FragColor = vec4(color.rgb, 1.0);
}

#define SCRNSVR 1
precision highp float;

#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;
uniform float speed;
uniform float size;
uniform float separation;
uniform float softness;
uniform float drift;
uniform vec3 color1;
uniform vec3 color2;
uniform vec3 color3;
uniform vec3 background;
uniform float brightness;
uniform float saturation;
#else
#define uTime iTime
#define uResolution iResolution.xy
const float speed = 0.3;
const float size = 0.38;
const float separation = 0.85;
const float softness = 0.006;
const float drift = 0.6;
const vec3 color1 = vec3(0.917647, 0.701961, 0.584314);
const vec3 color2 = vec3(0.592157, 0.368627, 0.474510);
const vec3 color3 = vec3(0.258824, 0.231373, 0.396078);
const vec3 background = vec3(0.090196, 0.109804, 0.200000);
const float brightness = 1.0;
const float saturation = 1.0;
#endif

// Static sub-byte dithering preserves broad gradients without temporal grain.
